/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Float, I, Lt, Mul, Poly, Pow, Sym, abs, add, isUnsolved, mul, nroots, pow, powsimp, rational, rootFactors, roots, rootsQuintic, symbols } from '../../src';
import { at, pyLen, strItems, sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.polys.polyroots", () => {
  // a primitive result that no library call returned
  //   roots(x**2 - 1, x)
  //   => {-1: 1, 1: 1}
  it.todo("roots(x**2 - 1, x)");
  // a primitive result that no library call returned
  //   roots(p)
  //   => {-1: 1, 1: 1}
  it.todo("roots(p)");
  // a primitive result that no library call returned
  //   roots(Poly(p, x))
  //   => {-sqrt(y): 1, sqrt(y): 1}
  it.todo("roots(Poly(p, x))");
  // a primitive result that no library call returned
  //   roots(x**2 - y, x)
  //   => {-sqrt(y): 1, sqrt(y): 1}
  it.todo("roots(x**2 - y, x)");
  // a primitive result that no library call returned
  //   roots([1, 0, -1])
  //   => {-1: 1, 1: 1}
  it.todo("roots([1, 0, -1])");
  // a primitive result that no library call returned
  //   roots((x-1)*(x**5-x+1), x)
  //   => {1: 1}
  it.todo("roots((x-1)*(x**5-x+1), x)");
  it("roots(x**7-3*x**2+1, x)", () => {
    expect(sympyStr(new Map())).toBe('{}');
  });
  it("sum(roots(f, x).values()) == degree(f, x)", () => {
    expect(sympyStr(rational(3).equals(rational(3)))).toBe('True');
  });
  it("sum(roots(f, x).values()) == degree(f, x) (2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("root_factors(x**2 - y, x)", () => {
    const [x, y] = symbols('x y');
    const v1 = rootFactors(add(pow(x, 2), mul(-1, y)), x);
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[x - sqrt(y), x + sqrt(y)]');
  });
});

